public class Solution {

    /*@ public normal_behavior
      @ requires x >= 0;
      @ ensures \result == x * x * x;
      @ also
      @ public normal_behavior
      @ requires x < 0;
      @ ensures \result == -((-x) * (-x) * (-x));
      @ also
      @ public normal_behavior
      @ requires true;
      @ ensures \result == x * x * x;
      @*/
    public static int solve(int x) {
        boolean neg = false;
        if (x < 0) {
            neg = true;
            x = -x;
        }
        int res = 0;
        /*@ loop_invariant i >= 0 && i <= x;
          @ loop_invariant res == i * x * x;
          @ decreases x - i;
          @*/
        for (int i = 0; i < x; i++) {
            /*@ loop_invariant j >= 0 && j <= x;
              @ loop_invariant res == i * x * x + j * x;
              @ decreases x - j;
              @*/
            for (int j = 0; j < x; j++) {
                /*@ loop_invariant k >= 0 && k <= x;
                  @ loop_invariant res == i * x * x + j * x + k;
                  @ decreases x - k;
                  @*/
                for (int k = 0; k < x; k++) {
                    res = res + 1;
                }
            }
        }
        return (neg ? -res : res);
    }

}

